def parse_nested_parens(paren_string: str) -> List[int]:
    max_depths = []
    current_depth = 0
    max_depth = 0

    for char in paren_string:
        if char == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif char == ')':
            current_depth -= 1
        else:
            continue  # Ignore spaces

        if char == ' ':
            max_depths.append(max_depth)
            max_depth = 0  # Reset for the next group

    # Append the last group's depth
    max_depths.append(max_depth)

    return max_depths
