    if (count_first + count_second) % 2 != 0:
        return 'No'

    # If the number of open parentheses in the first string is less than the number of open parentheses in the second string,
    # we can only form a balanced string by concatenating them in the correct order.
    if count_first > count_second:
        return 'No'

    return 'Yes'
