from datetime import datetime

def valid_date(date):
    if not date:
        return False

    # Split the date string into month, day, and year components
    try:
        month, day, year = map(int, date.split('-'))
    except ValueError:
        return False

    # Validate the month
    if not 1 <= month <= 12:
        return False

    # Validate the day
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if not 1 <= day <= 31:
            return False
    elif month in [4, 6, 9, 11]:
        if not 1 <= day <= 30:
            return False
    elif month == 2:
        if year % 4 == 0:
            if year % 100 == 0:
                if year % 400 == 0:
                    if not 1 <= day <= 29:
                        return False
                else:
                    if not 1 <= day <= 28:
                        return False
            else:
                if not 1 <= day <= 29:
                    return False
        else:
            if not 1 <= day <= 28:
                return False

    # Format validation
    try:
        datetime.strptime(date, '%m-%d-%Y')
        return True
    except ValueError:
        return False

# Test cases
