    """Check if the length of the intersection is a prime number and return the appropriate string."""
    intersection_length = intersection(interval1, interval2)
    if intersection_length:
        if is_prime(intersection_length[1] - intersection_length[0] + 1):
            return "YES"
        else:
            return "NO"
    else:
        return "NO"

