def minPath(grid, k):
    rows = len(grid)
    cols = len(grid[0])
    dp = [[[float('inf')] * (k + 1) for _ in range(cols)] for _ in range(rows)]

    # Fill the first row and first column
    for i in range(1, k + 1):
        dp[0][i][0] = grid[0][0]
    for j in range(1, k + 1):
        dp[j][0][0] = grid[0][0]
    for i in range(1, k + 1):
        dp[0][0][i] = grid[0][0]
    for j in range(1, k + 1):
        dp[0][j][0] = grid[0][j]

    # Fill the rest of the dp table
    for i in range(1, rows):
        for j in range(1, cols):
            for l in range(1, k + 1):
                dp[i][j][l] = min(dp[i - 1][j][l], dp[i][j - 1][l], dp[i + 1][j][l], dp[i][j + 1][l]) + grid[i][j]

    # Find the minimum path length
    min_len = float('inf')
    min_path = []
    for i in range(1, k + 1):
        if dp[rows - 1][cols - 1][i] < min_len:
            min_len = dp[rows - 1][cols - 1][i]
            min_path = [grid[rows - 1][cols - 1]]

    # Backtrack to find the path
    while min_len > 0:
        for i in range(rows - 1, -1, -1):
            for j in range(cols - 1, -1, -1):
                for l in range(1, k + 1):
                    if dp[i][j][l] == min_len:
                        if i > 0:
                            min_len = dp[i - 1][j][l - 1]
                            min_path.append(grid[i - 1][j])
                        elif j > 0:
                            min_len = dp[i][j - 1][l - 1]
                            min_path.append(grid[i][j - 1])
                        elif i < rows - 1:
                            min_len = dp[i + 1][j][l - 1]
                            min_path.append(grid[i + 1][j])
                        elif j < cols - 1:
                            min_len = dp[i][j + 1][l - 1]
                            min_path.append(grid[i][j + 1])
                        break
            if min_len == 0:
                break

    return min_path[::-1]

# Test cases
