            # For even n, the next number is 1 + n / 2
            next_number = 1 + i // 2
        else:
            # For odd n, the next number is the sum of the previous three numbers
            next_number = sequence[i - 1] + sequence[i - 2] + sequence[i - 3]
        sequence.append(next_number)

    return sequence
