def words_in_sentence(sentence):
    """
    Return a string of words from the original sentence where the word lengths are prime numbers.

    :param sentence: A string representing a sentence.
    :return: A string containing the prime-length words from the original sentence.
    """
    # List to store prime-length words
    prime_words = []
    # List to store prime numbers up to the maximum word length in the sentence
    primes = [2]

    # Function to check if a number is prime
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Generate prime numbers up to the maximum word length in the sentence
    max_word_length = 0
    for char in sentence:
        if char.isalpha():
            max_word_length = max(max_word_length, len(char))

    for num in range(5, max_word_length + 1, 6):
        if is_prime(num):
            primes.append(num)

    # Split the sentence into words
    words = sentence.split()

    # Filter words based on prime length
    for word in words:
        if len(word) in primes:
            prime_words.append(word)

    # Join the filtered words back into a string
    return ' '.join(prime_words)

