def do_algebra(operator, operand):
    def evaluate(stack):
        result = stack.pop()
        for op in reversed(operator):
            if op == '+':
                result += stack.pop()
            elif op == '-':
                result -= stack.pop()
            elif op == '*':
                result *= stack.pop()
            elif op == '//':
                result //= stack.pop()
            elif op == '**':
                result **= stack.pop()
        return result

    stack = []
    for op, val in zip(operator, operand):
        if op == '//':
            if len(stack) < 2:
                raise ValueError("Floor division requires at least two operands")
            stack.append(stack.pop() // stack.pop())
        elif op == '**':
            if len(stack) < 2:
                raise ValueError("Exponentiation requires at least two operands")
            stack.append(stack.pop() ** stack.pop())
        else:
            stack.append(val)

    return evaluate(stack)

